using UnityEngine;using System.Collections.Generic;
public class WoodlandGlowstick:MonoBehaviour {
 static readonly Queue<WoodlandGlowstick> active=new Queue<WoodlandGlowstick>();Light glow;Renderer shell;Material material;float age;Rigidbody body;
 public static bool Drop(WoodlandPlayer p){if(!p||p.cinematicLocked||p.anatomy.Incapacitated||p.IsReloading||p.equipment.ActionBusy||p.nodeRepair.Busy)return false;if(!p.inventory.Consume("glowstick",1)){p.inventory.Notify("No glow sticks · Search the reception supplies.");return false;}var go=GameObject.CreatePrimitive(PrimitiveType.Capsule);go.name="Dropped green glow stick";go.transform.position=p.eye.transform.position+p.eye.transform.forward*.45f-Vector3.up*.25f;go.transform.rotation=Quaternion.Euler(15,0,65);go.transform.localScale=new Vector3(.022f,.10f,.022f);var stick=go.AddComponent<WoodlandGlowstick>();stick.shell=go.GetComponent<Renderer>();stick.material=new Material(Shader.Find("Universal Render Pipeline/Lit"));stick.material.color=new Color(.12f,.8f,.2f);stick.material.EnableKeyword("_EMISSION");stick.material.SetColor("_EmissionColor",new Color(.12f,1,.22f)*3);stick.shell.material=stick.material;stick.glow=go.AddComponent<Light>();stick.glow.color=new Color(.2f,1,.3f);stick.glow.range=2;stick.glow.intensity=.28f;stick.glow.shadows=LightShadows.None;stick.body=go.AddComponent<Rigidbody>();stick.body.mass=.04f;stick.body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;stick.body.linearVelocity=p.eye.transform.forward*1.1f;while(active.Count>=8){var old=active.Dequeue();if(old)Destroy(old.gameObject);}active.Enqueue(stick);p.inventory.Notify("Glow stick dropped · Y drop another");return true;}
 void Update(){age+=Time.deltaTime;if(age>3&&body&&!body.isKinematic&&body.linearVelocity.sqrMagnitude<.01f){body.isKinematic=true;}float fade=Mathf.Clamp01((180-age)/30);glow.intensity=.28f*fade;material.SetColor("_EmissionColor",new Color(.12f,1,.22f)*3*fade);if(age>180)Destroy(gameObject);}
 void OnDestroy(){if(material)Destroy(material);}
}
